import{_ as s,a as p,b as n}from"./chunks/kdirectionalign_demo.CsxlEAxK.js";import{_ as e,o as t,a as c,b as i}from"./app.ejsEy6QV.js";const l="/ascendc.github.io/pr/6374/assets/mmad_kdirectionalign_c_api.Cbsf04fa.png",k=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算","link":"/api/SIMD-API/c_api/cube_compute/cube_compute"},{"text":"矩阵计算关键特性说明","link":"/api/SIMD-API/c_api/cube_compute/mmad_compute_key_features/mmad_compute_key_features"},{"text":"K方向对齐约束","link":"/api/SIMD-API/c_api/cube_compute/mmad_compute_key_features/k_direction_alignment_constraint"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_compute/mmad_compute_key_features/k_direction_alignment_constraint.md","filePath":"api/SIMD-API/c_api/cube_compute/mmad_compute_key_features/k_direction_alignment_constraint.md","lastUpdated":1789956443000}'),_={name:"api/SIMD-API/c_api/cube_compute/mmad_compute_key_features/k_direction_alignment_constraint.md"};function r(o,a,d,m,f,u){return t(),c("div",null,[...a[0]||(a[0]=[i('<div><article class="markdown-body"><h1>K方向对齐约束</h1><p><strong>特性说明：</strong></p><div data-filter="910b,A3"><p>Atlas A2系列产品/Atlas A3系列产品，asc_mmad接口支持开启此特性。</p></div><div data-filter="950"><p>Ascend 950PR&amp;950DT系列产品产品上L0A Buffer为Nz排布，非Zz排布，A矩阵转置非对齐float数据类型场景，L0A Buffer在K方向8对齐，无需开启此特性去确保计算正确性。</p></div><div data-filter="910b,A3"><p>K方向对齐的核心功能是通过k_direction_align参数控制在使用float数据类型（其他数据类型无需关注此特性）时，L0A Buffer和L0B Buffer矩阵在K方向上的对齐方式。</p><p>当设置k_direction_align = true时，L0A Buffer/L0B Buffer中的矩阵会将K方向对齐到 <code>ceil\\(K/16\\)\\*16</code>。</p><p><img src="'+l+'" alt="K方向对齐示意图"></p><p>例如，当K=44和K=36时，都会被对齐到48。在这种情况下，对于K=44，L0A Buffer/L0B Buffer中的12个分形块都会被完整读入CUBE；而对于K=36的情况，虽然对齐后也是48，但只有其中的10个分形块会被读入CUBE。</p><p><img src="'+s+'" alt="K方向对齐到48示意图"></p><p>当设置 <code>k_direction_align = false</code>时，L0A Buffer/L0B Buffer中的矩阵会将K方向对齐到 <code>ceil\\(K/8\\)\\*8</code>。</p><p>例如，当K=44时对齐到48，而K=36时对齐到40。在这种情况下，对于K=44，L0A Buffer/L0B Buffer中的12个分形块都会被完整读入CUBE；而对于K=36的情况，L0A Buffer/L0B Buffer中的10个分形块都会被读取到CUBE中。</p><p><img src="'+p+'" alt="K方向对齐到40示意图"></p><ol><li><p>A矩阵非转置的场景，无需开启k_direction_align。</p></li><li><p>A矩阵转置的场景，需要开启k_direction_align。</p></li></ol><p>当输入需要进行转置操作时，例如原始矩阵A的维度为K×M，在搬入L1 Buffer后，其存储形式会变为Nz排布（本质上仍为K×M）。此时应调用具备转置能力的矩阵搬入接口。该接口的内部实现如下图所示：在K方向上会进行16的对齐处理（如左图所示）。完成转置后，数据将呈现出如右图所示的Zz分形形式，存储在L0A Buffer中。为了避免读入无效数据，可以通过开启k_direction_align参数，仅读取有效分形的数据。</p><p><img src="'+n+`" alt="K方向对齐转置示意图"></p><p><strong>使用示例：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">asc_mmad</span><span class="p">(</span><span class="n">c</span><span class="p">,</span><span class="w"> </span><span class="n">a</span><span class="p">,</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">k</span><span class="p">,</span><span class="w"> </span><span class="n">n</span><span class="p">,</span><span class="w"> </span><span class="n">asc_unit_flag_mode</span><span class="o">::</span><span class="n">DISABLE</span><span class="p">,</span>
<span class="w">         </span><span class="nb">true</span><span class="w"> </span><span class="cm">/* k_direction_align */</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="nb">true</span><span class="p">);</span>
</code></pre></div></div></article></div>`,1)])])}const B=e(_,[["render",r]]);export{k as __pageData,B as default};
